    "unavailable": "Model service is unavailable. Check Models & services and retry. Existing data may be stale.",
    "partial": "Some data could not be refreshed. Retry.",
    "noTools": "No tool usage in this period",
    "noLimits": "No provider limits available",
    "noRecords": "No records in this period",
    "noSessions": "No sessions in this period",
